/bin/zsh -lc "rtk python3 -c 'from html.parser import HTMLParser; from pathlib import Path
class P(HTMLParser):
 def __init__(self): super().__init__(); self.title=False; self.titles=[]; self.videos=[]; self.headings=[]
 def handle_starttag(self,t,a):
  d=dict(a)
  if t==\"title\": self.title=True
  if t==\"video\": self.videos.append(d)
  if t in (\"h1\",\"h2\",\"h3\"): self.headings.append(t)
 def handle_endtag(self,t):
  if t==\"title\": self.title=False
 def handle_data(self,s):
  if self.title: self.titles.append(s)
p=P(); p.feed(Path(\"index.html\").read_text()); print({\"title\":\"\".join(p.titles),\"videos\":p.videos,\"headings\":p.headings,\"source_exists\":Path(p.videos[0][\"src\"]).exists()})' "

